mapper.select:
SELECT r.id FROM crawl_run r
JOIN crawl_task t ON t.id = r.task_id AND t.enabled = TRUE
JOIN data_source s ON s.id = t.source_id AND s.enabled = TRUE
WHERE r.status = 'PAUSED' AND r.completion_reason = 'QUOTA_EXHAUSTED'
  AND r.deferred_until <= #{now}
ORDER BY r.deferred_until, r.id LIMIT #{limit}

mapper.insert:
INSERT INTO crawl_task (
    source_id, task_name, parameter_version, parameters_json, parameter_hash,
    enabled, version, created_by, created_at, updated_at
) VALUES (
    #{sourceId}, #{taskName}, #{parameterVersion}, #{parametersJson}, #{parameterHash},
    TRUE, 0, #{createdBy}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT COUNT(*)
FROM crawl_run r
JOIN crawl_task t ON t.id = r.task_id
WHERE t.source_id = #{sourceId}
  AND r.parameter_hash = #{parameterHash}
  AND r.status IN ('PENDING', 'RUNNING', 'PAUSING', 'PAUSED', 'CANCELLING')

mapper.insert:
INSERT INTO crawl_run (
    task_id, run_number, trigger_type, status, requested_by, parent_run_id, parameter_hash,
    range_start, range_end, created_at, updated_at
) VALUES (
    #{taskId}, #{runNumber}, #{triggerType}, 'PENDING', #{requestedBy}, #{parentRunId}, #{parameterHash},
    #{rangeStart}, #{rangeEnd}, #{createdAt}, #{createdAt}
)

mapper.select:
SELECT id, task_id, schedule_key, local_time, time_zone, incremental_mode,
       next_fire_at, enabled, version
FROM crawl_schedule WHERE task_id = #{taskId}
